const filas = $('Leer agentes').all().map(i => i.json).filter(a => a && a.calendar_id && a.active === true);
const out = filas.map(a => ({ json: { agent_key: a.agent_key, display_name: a.display_name, calendar_id: a.calendar_id } }));
